// Analisar mensagem e determinar intenção
const contexto = JSON.parse($json.contexto);
const mensagem = contexto.mensagem_original.toLowerCase();
const imoveis = $input.all().slice(1); // Pular o primeiro item que é o contexto

// Detectar intenções relacionadas a agendamento
const intencoes = {
  agendar: ['agendar', 'visita', 'visitar', 'conhecer', 'ver', 'marcar'],
  horario: ['horário', 'hora', 'quando', 'disponível', 'livre'],
  hoje: ['hoje', 'agora', 'já'],
  amanha: ['amanhã', 'tomorrow'],
  semana: ['semana', 'próxima semana'],
  manha: ['manhã', 'morning', '9h', '10h', '11h'],
  tarde: ['tarde', 'afternoon', '14h', '15h', '16h', '17h'],
  noite: ['noite', 'evening', '18h', '19h', '20h'],
  fim_semana: ['sábado', 'domingo', 'fim de semana', 'weekend']
};

// Detectar intenção principal
let intencao_principal = 'listar_imoveis';
for (const [intencao, palavras] of Object.entries(intencoes)) {
  if (palavras.some(palavra => mensagem.includes(palavra))) {
    if (intencao === 'agendar') {
      intencao_principal = 'agendar_visita';
      break;
    }
  }
}

// Detectar preferências de horário
const preferencias_horario = {
  periodo: null,
  dia_preferencia: null,
  urgencia: 'normal'
};

if (intencoes.hoje.some(palavra => mensagem.includes(palavra))) {
  preferencias_horario.urgencia = 'alta';
  preferencias_horario.dia_preferencia = 'hoje';
}

if (intencoes.manha.some(palavra => mensagem.includes(palavra))) {
  preferencias_horario.periodo = 'manha';
} else if (intencoes.tarde.some(palavra => mensagem.includes(palavra))) {
  preferencias_horario.periodo = 'tarde';
} else if (intencoes.noite.some(palavra => mensagem.includes(palavra))) {
  preferencias_horario.periodo = 'noite';
}

// Processar lista de imóveis
const imoveis_formatados = imoveis.map((item, index) => {
  const imovel = item.json;
  return {
    id: imovel.id,
    codigo: imovel.codigo_interno,
    tipo: imovel.tipo,
    endereco: `${imovel.endereco}, ${imovel.bairro}`,
    valor: imovel.valor,
    quartos: imovel.quartos,
    banheiros: imovel.banheiros,
    area: imovel.area_construida,
    corretor: imovel.corretor_nome,
    posicao: index + 1
  };
});

return {
  json: {
    contexto_original: contexto,
    intencao_principal: intencao_principal,
    preferencias_horario: preferencias_horario,
    imoveis_disponiveis: imoveis_formatados,
    total_imoveis: imoveis_formatados.length
  }
};

// Gerar resposta baseada na intenção
const dados = $json;
const intencao = dados.intencao_principal;
const imoveis = dados.imoveis_disponiveis;
const canal = dados.contexto_original.canal;

let resposta = '';

if (intencao === 'agendar_visita') {
  // Buscar horários do segundo input
  const horariosInput = $input.all()[1]; // Segundo input são os horários
  const horarios = horariosInput ? [horariosInput.json] : [];

  if (horarios.length > 0) {
    const horariosFormatados = horarios.slice(0, 5).map((h, index) => {
      const data = new Date(h.data_hora_inicio);
      const dataFormatada = data.toLocaleDateString('pt-BR', {
        weekday: 'long',
        day: '2-digit',
        month: '2-digit'
      });
      const horaFormatada = data.toLocaleTimeString('pt-BR', {
        hour: '2-digit',
        minute: '2-digit'
      });

      return `${index + 1}. ${dataFormatada} às ${horaFormatada} (${h.corretor_nome})`;
    }).join('\n');

    if (canal === 'whatsapp') {
      resposta = `Perfeito! 🗓️ Vou agendar sua visita!

Tenho estes horários disponíveis:

${horariosFormatados}

Qual horário funciona melhor para você? É só me falar o número da opção! 😊`;
    } else {
      resposta = `Ótimo! Tenho os seguintes horários disponíveis para visita:

${horariosFormatados}

Por favor, me informe qual horário é melhor para você.`;
    }
  } else {
    if (canal === 'whatsapp') {
      resposta = `Que pena! 😔 No momento não temos horários disponíveis nos próximos dias.

Mas não se preocupe! Vou anotar seu interesse e assim que surgir uma agenda, te aviso imediatamente!

Enquanto isso, posso te enviar mais detalhes dos imóveis por aqui mesmo. O que acha? 📱`;
    } else {
      resposta = `Infelizmente não temos horários disponíveis nos próximos dias.

Vou registrar seu interesse e entrar em contato assim que houver disponibilidade.

Enquanto isso, posso enviar mais informações sobre os imóveis disponíveis.`;
    }
  }
} else {
  // Listar imóveis disponíveis
  if (imoveis.length > 0) {
    const imoveisFormatados = imoveis.map(imovel => {
      const valorFormatado = new Intl.NumberFormat('pt-BR', {
        style: 'currency',
        currency: 'BRL'
      }).format(imovel.valor);

      if (canal === 'whatsapp') {
        return `🏠 *${imovel.codigo}* - ${imovel.tipo.toUpperCase()}
📍 ${imovel.endereco}
💰 ${valorFormatado}
🛏️ ${imovel.quartos || 0} quartos | 🚿 ${imovel.banheiros || 0} banheiros
📐 ${imovel.area || 0}m²`;
      } else {
        return `${imovel.codigo} - ${imovel.tipo.toUpperCase()}
Endereço: ${imovel.endereco}
Valor: ${valorFormatado}
Quartos: ${imovel.quartos || 0} | Banheiros: ${imovel.banheiros || 0}
Área: ${imovel.area || 0}m²`;
      }
    }).join('\n\n');

    if (canal === 'whatsapp') {
      resposta = `Encontrei ${imoveis.length} imóveis perfeitos para você! 🎉

${imoveisFormatados}

✨ Gostou de algum? Me fala qual te interessou mais e vamos agendar uma visita! 

Ou se preferir, posso enviar mais detalhes e fotos de qualquer um deles! 📸`;
    } else {
      resposta = `Encontrei ${imoveis.length} imóveis que atendem seu perfil:

${imoveisFormatados}

Gostaria de agendar uma visita para algum deles ou receber mais informações?`;
    }
  } else {
    if (canal === 'whatsapp') {
      resposta = `Ops! 😅 No momento não temos imóveis disponíveis que atendam exatamente seu perfil.

Mas calma! Recebemos novos imóveis toda semana! 🏠

Vou cadastrar seu interesse e te avisar assim que chegar algo perfeito para você!

Enquanto isso, que tal ampliarmos um pouco os critérios? Posso buscar em bairros próximos ou com valores um pouco diferentes. O que acha? 🤔`;
    } else {
      resposta = `No momento não temos imóveis disponíveis que atendam exatamente seus critérios.

Vou registrar seu interesse e entrar em contato assim que recebermos novos imóveis.

Gostaria que eu amplie a busca para bairros próximos ou faixas de valor similares?`;
    }
  }
}

return {
  json: {
    resposta: resposta,
    intencao_processada: intencao,
    imoveis_apresentados: imoveis,
    proxima_acao: intencao === 'agendar_visita' ? 'aguardar_escolha_horario' : 'aguardar_interesse_imovel',
    dados_contexto: dados
  }
};

// Gerar resposta para listagem de imóveis
const dados = $json;
const imoveis = dados.imoveis_disponiveis;
const canal = dados.contexto_original.canal;
const cliente = dados.contexto_original.dados_entrada.cliente;

let resposta = '';

if (imoveis.length > 0) {
  const imoveisFormatados = imoveis.map(imovel => {
    const valorFormatado = new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(imovel.valor);

    if (canal === 'whatsapp') {
      return `🏠 *${imovel.codigo}* - ${imovel.tipo.toUpperCase()}
📍 ${imovel.endereco}
💰 ${valorFormatado}
🛏️ ${imovel.quartos || 0} quartos | 🚿 ${imovel.banheiros || 0} banheiros
📐 ${imovel.area || 0}m²`;
    } else {
      return `${imovel.codigo} - ${imovel.tipo.toUpperCase()}
Endereço: ${imovel.endereco}
Valor: ${valorFormatado}
Quartos: ${imovel.quartos || 0} | Banheiros: ${imovel.banheiros || 0}
Área: ${imovel.area || 0}m²`;
    }
  }).join('\n\n');

  const nomeCliente = cliente?.nome?.split(' ')[0] || 'Cliente';

  if (canal === 'whatsapp') {
    resposta = `Oi ${nomeCliente}! 😊

Encontrei ${imoveis.length} imóveis incríveis que combinam com o que você está procurando! 🎯

${imoveisFormatados}

✨ *Gostou de algum?*

Posso te enviar:
📸 Mais fotos
📋 Detalhes completos  
🗓️ Agendar uma visita

É só me falar qual te interessou mais! 👆`;
  } else {
    resposta = `Olá ${nomeCliente}!

Encontrei ${imoveis.length} imóveis que atendem seu perfil:

${imoveisFormatados}

Gostaria de:
- Receber mais informações sobre algum imóvel específico
- Agendar uma visita
- Ver fotos adicionais

Por favor, me informe como posso ajudar.`;
  }
} else {
  if (canal === 'whatsapp') {
    resposta = `Oi! 😅

Pesquisei aqui e no momento não temos imóveis disponíveis que atendam exatamente seu perfil.

*Mas tenho uma boa notícia!* 📢
Recebemos novos imóveis toda semana!

Vou:
✅ Cadastrar seu interesse
✅ Te avisar assim que chegar algo perfeito
✅ Buscar opções similares

Enquanto isso, que tal ampliarmos um pouco a busca? Posso procurar:
📍 Bairros próximos
💰 Faixas de valor similares
🏠 Tipos de imóvel parecidos

O que acha? 🤔`;
  } else {
    resposta = `Olá!

No momento não temos imóveis disponíveis que atendam exatamente seus critérios de busca.

Vou registrar seu interesse em nosso sistema e entrar em contato assim que recebermos novos imóveis que correspondam ao seu perfil.

Gostaria que eu amplie a busca considerando:
- Bairros próximos à sua região de interesse
- Faixas de valor similares
- Tipos de imóvel relacionados

Por favor, me informe se deseja que eu faça essa busca ampliada.`;
  }
}

return {
  json: {
    resposta: resposta,
    imoveis_apresentados: imoveis,
    proxima_acao: 'aguardar_interesse_imovel',
    dados_contexto: dados
  }
};
